#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[])
{
    /* ----- argument handling ----- */
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    char *endptr = NULL;
    long n = strtol(argv[1], &endptr, 10);

    /* invalid number (no conversion) */
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    /* out‑of‑range check (the original binary used 1 000 000 000) */
    if (n > 1000000000L) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* numbers smaller than 2 have no prime factors */
    if (n < 2) {
        puts("NONE");
        return 0;
    }

    /* ----- prime factorisation ----- */
    int first = 1;              /* flag to control leading space */

    for (long p = 2; p * p <= n; ++p) {
        if (n % p != 0)
            continue;

        int exp = 0;
        while (n % p == 0) {
            n /= p;
            ++exp;
        }

        if (!first) putchar(' ');
        printf("%ld^%d", p, exp);
        first = 0;
    }

    /* if a prime factor larger than sqrt(original) remains */
    if (n > 1) {
        if (!first) putchar(' ');
        printf("%ld^1", n);
    }

    putchar('\n');
    return 0;
}
